			val /= static_cast<num_t>(nn);
			val += static_cast<num_t>(1);
			A[state] = val;
		} else if (j == i) {
			A[state] = static_cast<num_t>(1);
		} else { // j > i
			A[state] = static_cast<num_t>(0);
		}
	});

	// Make the matrix positive semi-definite:
	// B[r][s] = sum_t A[r][t] * A[s][t]; then A = B
	auto B = noarr::bag(A.structure());

	// Build a traverser over the artificial t-dimension once and reuse it.
	auto t_trav = traverser(t_structure).order(set_length<'t'>(n));

	// For each (r,s) compute the inner product of row r and row s of A.
	// Compared to the original t–outer / (r,s)–inner traversal, this version
	// keeps the accumulator in a register and touches each B[r][s] only once,
	// while preserving the per-element arithmetic order.
	traverser(B).for_each([&](auto rs_state) {
		auto [r, s] = get_indices<'i', 'j'>(rs_state);

		num_t sum = static_cast<num_t>(0);

		t_trav.for_each([&](auto t_state) {
			auto t = get_index<'t'>(t_state);

			auto rt_state = noarr::idx<'i', 'j'>(r, t);
			auto st_state = noarr::idx<'i', 'j'>(s, t);

			sum += A[rt_state] * A[st_state];
		});

		B[rs_state] = sum;
	});

	// Copy B back into A
	traverser(A, B).for_each([&](auto state) {
		A[state] = B[state];
	});
}

