[[gnu::flatten, gnu::noinline]]
void kernel_lu(auto A) {
	// A: i x j (n x n)
	using namespace noarr;

	auto n = A | get_length<'i'>();
	(void)n; // n is unused now but kept for clarity / possible future tuning

	#pragma scop
	// Outer loop over i (rows).
	traverser(A).template for_dims<'i'>([&](auto trav_i) {
		auto state_i = trav_i.state();
		auto i_idx = get_index<'i'>(state_i);

		// Pre-build the k-traverser for the second inner loop (j >= i).
		// Length depends only on i, so it is reused for all such j in this row.
		auto k_trav_i = traverser(k_structure).order(set_length<'k'>(i_idx));

		// Inner loop over all columns j. We handle both original ranges
		//   - 0 <= j <  i  (L-part),
		//   - i <= j <  n  (U-part),
		// in a single traversal and branch on j, keeping the same j-order.
		trav_i.template for_dims<'j'>([&](auto trav_ij) {
			auto state_ij = trav_ij.state();
			auto j_idx = get_index<'j'>(state_ij);

			// State for A[i][j]
			auto ij_state = state_ij;

			// Keep A[i][j] in a local accumulator so that all updates happen
			// in registers and we load/store A[i][j] only once. This preserves
			// the arithmetic order of the original code.
			num_t a_ij = A[ij_state];

			if (j_idx < i_idx) {
				// First inner loop body: 0 <= j < i
				// for (k = 0; k < j; k++)
				if (j_idx > 0) {
					auto k_trav_j =
						traverser(k_structure).order(set_length<'k'>(j_idx));

					k_trav_j.for_each([&](auto k_state) {
						auto k_idx = get_index<'k'>(k_state);

						auto ik_state = noarr::idx<'i', 'j'>(i_idx, k_idx);
						auto kj_state = noarr::idx<'i', 'j'>(k_idx, j_idx);

						a_ij -= A[ik_state] * A[kj_state];
					});
				}

				// A[i][j] /= A[j][j];
				auto jj_state = noarr::idx<'i', 'j'>(j_idx, j_idx);
				a_ij /= A[jj_state];

				A[ij_state] = a_ij;
			} else { // j_idx >= i_idx
				// Second inner loop body: i <= j < n
				// for (k = 0; k < i; k++)
				if (i_idx > 0) {
					k_trav_i.for_each([&](auto k_state) {
						auto k_idx = get_index<'k'>(k_state);

						auto ik_state = noarr::idx<'i', 'j'>(i_idx, k_idx);
						auto kj_state = noarr::idx<'i', 'j'>(k_idx, j_idx);

						a_ij -= A[ik_state] * A[kj_state];
					});
				}

				A[ij_state] = a_ij;
			}
		});
	});
	#pragma endscop
