constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();
constexpr auto t_vec = noarr::vector<'t'>();

struct tuning {
	// A: i x j
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec); // j = inner (contiguous), i = outer (row-major)
} tuning;

// 1D helper structures for k- and t-iterations (no actual data, only for traversal)
constexpr auto k_structure = noarr::scalar<char>() ^ k_vec;
constexpr auto t_structure = noarr::scalar<char>() ^ t_vec;

// initialization function
void init_array(auto A) {
	// A: i x j
	using namespace noarr;

	// matrix is n x n
	auto n = A | get_length<'i'>();

	// Precompute invariants used in the fill
	const int   nn         = static_cast<int>(n);
	const num_t one_over_n = static_cast<num_t>(1) / static_cast<num_t>(nn);

	// -------------------------------------------------------------------------
	// 1) Initialize A as unit-lower + some values below diagonal, 0 above
	// -------------------------------------------------------------------------
	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		const int jj = static_cast<int>(j);

		if (j < i) {
			// A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
			// Keep the exact arithmetic as in the original code, but reuse 1/n.
			const num_t num = static_cast<num_t>((-jj % nn));
			A[state] = num * one_over_n + static_cast<num_t>(1);
		} else if (j == i) {
			A[state] = static_cast<num_t>(1);
		} else { // j > i
			A[state] = static_cast<num_t>(0);
		}
	});

	// -------------------------------------------------------------------------
	// 2) Make the matrix positive semi-definite:
	//
	//    B[r][s] = sum_t A[r][t] * A[s][t];  then A = B
	//
	// Optimized version:
	//  - Compute each dot product once in a local accumulator and store the
	//    result to B[r][s].
	//  - Exploit symmetry B[r][s] == B[s][r] by mirroring instead of computing
	//    the same sum twice.
	//  - This keeps the arithmetic for each (r,s) identical to the original:
	//      sum over t in increasing order
	// -------------------------------------------------------------------------

	// Allocate B with the same structure as A (uninitialized).
	auto B = noarr::bag(A.structure());

	// 1D traverser over t, reused for all dots to avoid recreating traversers
	auto t_trav = traverser(t_structure).order(set_length<'t'>(n));

	// Iterate over rows r
	traverser(B).template for_dims<'i'>([&](auto trav_i) {
		auto state_i = trav_i.state();
		auto r       = get_index<'i'>(state_i);

		// For each row r, only iterate columns s >= r.
		// We then mirror B[r][s] into B[s][r] when r != s.
		auto trav_upper = trav_i.order(noarr::slice<'j'>(r, n - r));

		trav_upper.template for_dims<'j'>([&](auto trav_rs) {
			auto state_rs = trav_rs.state();
			auto s        = get_index<'j'>(state_rs);

			// Accumulate the dot product of row r and row s into a register
			num_t acc = static_cast<num_t>(0);

			t_trav.for_each([&](auto t_state) {
				auto t = get_index<'t'>(t_state);

				auto rt_state = noarr::idx<'i', 'j'>(r, t);
				auto st_state = noarr::idx<'i', 'j'>(s, t);

				acc += A[rt_state] * A[st_state];
			});

			// Write the computed value to B[r][s]
			B[state_rs] = acc;

			// Enforce symmetry by mirroring when r != s
			if (s != r) {
				auto sr_state = noarr::idx<'i', 'j'>(s, r);
				B[sr_state]   = acc;
			}
		});
	});

	// Copy B back into A (full n x n)
	traverser(A, B).for_each([&](auto state) {
		A[state] = B[state];
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_lu(auto A) {
	// A: i x j (n x n)
	using namespace noarr;

	auto n = A | get_length<'i'>();

	// Pre-build a 1D traverser for k in [0, n).
	// Individual j/i-dependent limits are then applied using slice over this.
	auto k_trav_full = traverser(k_structure).order(set_length<'k'>(n));

	#pragma scop
	traverser(A).template for_dims<'i'>([&](auto trav_i) {
		auto state_i = trav_i.state();
		auto i_idx   = get_index<'i'>(state_i);

		// Single pass over all columns j for this row i.
		// For j < i:  A[i][j] -= sum_{k < j} A[i][k] * A[k][j]; then A[i][j] /= A[j][j]
		// For j >= i: A[i][j] -= sum_{k < i} A[i][k] * A[k][j]
		trav_i.template for_dims<'j'>([&](auto trav_ij) {
			auto state_ij = trav_ij.state();
			auto j_idx    = get_index<'j'>(state_ij);

			// state_ij already identifies A[i][j]
			auto ij_state = state_ij;

			// Determine the upper bound for k:
			//  - lower part (j < i): k in [0, j)
			//  - upper part (j >= i): k in [0, i)
			std::size_t k_limit = (j_idx < i_idx) ? j_idx : i_idx;

			// Perform the rank-1 updates if the range is non-empty
			if (k_limit > 0) {
				// Restrict k to [0, k_limit)
				auto k_trav = k_trav_full.order(slice<'k'>(0, k_limit));

				k_trav.for_each([&](auto k_state) {
					auto k_idx   = get_index<'k'>(k_state);
					auto ik_state = noarr::idx<'i', 'j'>(i_idx, k_idx);
					auto kj_state = noarr::idx<'i', 'j'>(k_idx, j_idx);

					A[ij_state] -= A[ik_state] * A[kj_state];
				});
			}

			// For the strictly lower triangular part, divide by the diagonal A[j][j].
			if (j_idx < i_idx) {
				auto jj_state = noarr::idx<'i', 'j'>(j_idx, j_idx);
				A[ij_state]  /= A[jj_state];
			}
		});
	});
	#pragma endscop
}

