#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp> // for serialize_data

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "lu.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();
constexpr auto t_vec = noarr::vector<'t'>();

struct tuning {
	// A: i x j  (i and j are both of dynamic length, set later)
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);
} tuning;

// 1D helper structures for k- and t-iterations (no actual data, only for traversal)
constexpr auto k_structure = noarr::scalar<char>() ^ k_vec;
constexpr auto t_structure = noarr::scalar<char>() ^ t_vec;

// ========================= initialization =========================
// initialization function
//
// This does two things:
//  1) Initializes A to a unit-lower matrix with some values below the diagonal and 0 above.
//  2) Forms a positive semi-definite matrix by computing A := A * A^T.
//
// The second step is implemented as a sequence of dot-products for every pair (r,s):
//   B[r,s] = sum_t A[r,t] * A[s,t]
// Using a local accumulator improves locality and *dramatically* reduces writes to B
// compared to the original version, which updated B[r,s] in every t-iteration.
void init_array(auto A) {
	using namespace noarr;

	// A: i x j, with i- and j-length both equal to n (n x n)
	auto n = A | get_length<'i'>();

	// ----------------------------------------------------------------
	// 1) Initialize A as unit-lower plus some values below diagonal, 0 above
	// ----------------------------------------------------------------
	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		const int nn = static_cast<int>(n);
		const int jj = static_cast<int>(j);

		if (j < i) {
			// Original initialization:
			//   A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
			// Keep the division form to preserve numerical behavior.
			num_t val = static_cast<num_t>((-jj % nn));
			val /= static_cast<num_t>(nn);
			val += static_cast<num_t>(1);
			A[state] = val;
		} else if (j == i) {
			A[state] = static_cast<num_t>(1);
		} else { // j > i
			A[state] = static_cast<num_t>(0);
		}
	});

	// ----------------------------------------------------------------
	// 2) Make the matrix positive semi-definite:
	//    B[r][s] = sum_t A[r][t] * A[s][t];  then A := B
	// ----------------------------------------------------------------
	auto B = noarr::bag(A.structure());

	// Compute each entry of B as a dot product between rows r and s.
	// This keeps all partial sums in a register and writes B[r,s] only once,
	// while preserving the exact summation order over t used in the original
	// code (t = 0 .. n-1) for each (r,s) pair.
	traverser(B).for_each([&](auto rs_state) {
		auto [r, s] = get_indices<'i', 'j'>(rs_state);

		num_t acc = static_cast<num_t>(0);

		// Iterate t dimension: 0 <= t < n
		traverser(t_structure)
			.order(noarr::set_length<'t'>(n))
			.for_each([&](auto t_state) {
				auto t = get_index<'t'>(t_state);

				auto rt_state = noarr::idx<'i', 'j'>(r, t);
				auto st_state = noarr::idx<'i', 'j'>(s, t);

				acc += A[rt_state] * A[st_state];
			});

		B[rs_state] = acc;
	});

	// Copy B back into A
	traverser(A, B).for_each([&](auto state) {
		A[state] = B[state];
	});
}

// ========================= computation kernel =========================
//
// LU factorization without pivoting.
// Layout: A is i x j (n x n). We keep the original algorithmic structure
// but re-order the *second* inner loop to improve data locality:
//
//   Original upper-part update (for a fixed i):
//     for j = i .. n-1
//       for k = 0 .. i-1
//         A[i][j] -= A[i][k] * A[k][j];
//
//   Optimized version:
//     for k = 0 .. i-1
//       let lik = A[i][k];   // load once
//       for j = i .. n-1
//         A[i][j] -= lik * A[k][j];
//
// For every (i,j) the updates are still applied in increasing k, so the
// arithmetic order is unchanged; we merely reuse A[i][k] across all j,
// which improves cache usage and reduces memory traffic.
//
// The lower-part (j < i) loop cannot be reordered in the same way because
// of true data dependencies between A[i][j] and previously computed
// A[i][k] (k<j). We therefore keep it in its original (i, j, k) order.
[[gnu::flatten, gnu::noinline]]
void kernel_lu(auto A) {
	using namespace noarr;

	// A: i x j (n x n)
	auto n = A | get_length<'i'>();

	#pragma scop
	traverser(A).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has 'i' fixed, 'j' remaining
		auto state_i = trav_i.state();
		auto i_idx = get_index<'i'>(state_i);

		// ------------------------------------------------------------
		// First inner loop: 0 <= j < i
		// Computes the L part (below diagonal) of row i.
		// This loop has inherent dependencies in j, so we keep
		// the original order but rely on Noarr traversers.
		// ------------------------------------------------------------
		if (i_idx > 0) {
			// View of j in [0, i_idx)
			auto trav_j_lt_i = trav_i.order(noarr::slice<'j'>(0, i_idx));

			trav_j_lt_i.template for_dims<'j'>([&](auto trav_ij) {
				auto state_ij = trav_ij.state();
				auto j_idx = get_index<'j'>(state_ij);

				// State for A[i][j]
				auto ij_state = noarr::idx<'i', 'j'>(i_idx, j_idx);

				// A[i][j] -= sum_{k=0}^{j-1} A[i][k] * A[k][j];
				// The sum uses already finalized L[i][k] values
				// from previous j iterations.
				if (j_idx > 0) {
					traverser(k_structure)
						.order(noarr::set_length<'k'>(j_idx))
						.for_each([&](auto k_state) {
							auto k_idx = get_index<'k'>(k_state);

							auto ik_state = noarr::idx<'i', 'j'>(i_idx, k_idx);
							auto kj_state = noarr::idx<'i', 'j'>(k_idx, j_idx);

							A[ij_state] -= A[ik_state] * A[kj_state];
						});
				}

				// Finalize L[i][j] by dividing with U[j][j].
				auto jj_state = noarr::idx<'i', 'j'>(j_idx, j_idx);
				A[ij_state] /= A[jj_state];
			});
		}

		// ------------------------------------------------------------
		// Second inner loop: i <= j < n
		// Computes the U part (diagonal and above) of row i.
		// We change the loop order from (j,k) to (k,j) to:
		//   - load A[i][k] once per k,
		//   - traverse j contiguously (better spatial locality),
		// while preserving the order of k-accumulations for each j.
		// ------------------------------------------------------------
		auto len_second = n - i_idx; // length of j-range [i_idx, n)
		if (len_second > 0 && i_idx > 0) {
			// View of j in [i_idx, n)
			auto trav_j_ge_i = trav_i.order(noarr::slice<'j'>(i_idx, len_second));

			// for (k = 0; k < i; k++)
			traverser(k_structure)
				.order(noarr::set_length<'k'>(i_idx))
				.for_each([&](auto k_state) {
					auto k_idx = get_index<'k'>(k_state);

					// Load A[i][k] once and reuse it for all j >= i
					auto ik_state = noarr::idx<'i', 'j'>(i_idx, k_idx);
					num_t aik = A[ik_state];

					// for (j = i; j < n; j++)
					trav_j_ge_i.template for_dims<'j'>([&](auto trav_ij) {
						auto state_ij = trav_ij.state();
						auto j_idx = get_index<'j'>(state_ij);

						auto kj_state = noarr::idx<'i', 'j'>(k_idx, j_idx);

						// A[i][j] -= A[i][k] * A[k][j];
						A[state_ij] -= aik * A[kj_state];
					});
				});
		}
		// Note: for i_idx == 0, the original algorithm's inner loop
		//       "for(k = 0; k < i; k++)" is empty, so skipping the
		//       whole block is correct.
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	auto set_lengths =
		noarr::set_length<'i'>(n) ^
