		// This view has only the 'j' dimension, so accesses A[i][*] become
		// cheaper and more cache-friendly.
		auto A_row_i = A ^ noarr::fix<'i'>(i_idx);

		// ------------------------------------------------------------------
		// First inner loop: 0 <= j < i   (computes L(i, j))
		// ------------------------------------------------------------------
		if (i_idx > 0) {
			// Restrict the row view to columns [0, i_idx)
			auto trav_j_lt_i =
				noarr::traverser(A_row_i).order(noarr::slice<'j'>(0, i_idx));

			// Iterate over all j in the slice
			trav_j_lt_i.template for_dims<'j'>([&](auto trav_j) {
				auto state_j = trav_j.state();
				auto j_idx = get_index<'j'>(state_j);

				// Column view with this j fixed; has only the 'i' dimension.
				auto A_col_j = A ^ noarr::fix<'j'>(j_idx);

				// Start from the current A[i][j] value and accumulate updates
				// in a register instead of repeatedly writing back to memory.
				num_t sum = A_row_i[trav_j];

				// for (k = 0; k < j; k++)
				//   sum -= A[i][k] * A[k][j];
				if (j_idx > 0) {
					traverser(k_structure)
						.order(noarr::set_length<'k'>(j_idx))
						.for_each([&](auto k_state) {
							auto k_idx = get_index<'k'>(k_state);

							// A[i][k]: row view
							num_t aik = A_row_i[noarr::idx<'j'>(k_idx)];
							// A[k][j]: column view
							num_t akj = A_col_j[noarr::idx<'i'>(k_idx)];

							sum -= aik * akj;
						});
				}

				// A[i][j] /= A[j][j];
				num_t ajj = A_col_j[noarr::idx<'i'>(j_idx)];
				sum /= ajj;

				A_row_i[trav_j] = sum;
			});
		}

		// ------------------------------------------------------------------
		// Second inner loop: i <= j < n   (computes U(i, j))
		// ------------------------------------------------------------------
		auto len_second = n - i_idx;
		if (len_second > 0) {
			// Restrict the row view to columns [i_idx, n)
			auto trav_j_ge_i =
				noarr::traverser(A_row_i).order(noarr::slice<'j'>(i_idx, len_second));

			trav_j_ge_i.template for_dims<'j'>([&](auto trav_j) {
				auto state_j = trav_j.state();
				auto j_idx = get_index<'j'>(state_j);

				auto A_col_j = A ^ noarr::fix<'j'>(j_idx);

				// Accumulate updates in a register:
				// A[i][j] -= sum_{k=0}^{i-1} A[i][k] * A[k][j]
				num_t sum = A_row_i[trav_j];

