	// Outer loop over rows i
	traverser(A).template for_dims<'i'>([&](auto trav_i) {
		const auto state_i = trav_i.state();
		const std::size_t i_idx = get_index<'i'>(state_i);

		// -----------------------------------------------------------------
		// 1) Compute L-part for this row: columns 0 <= j < i
		//
		//    for (j = 0; j < i; ++j) {
		//        for (k = 0; k < j; ++k)
		//            A[i][j] -= A[i][k] * A[k][j];
		//        A[i][j] /= A[j][j];
		//    }
		//
		// We keep the (i -> j -> k) order exactly, so the sequence of
		// floating‑point operations is unchanged.
		// -----------------------------------------------------------------
		if (i_idx > 0) {
			// View of the current row restricted to j in [0, i_idx)
			auto trav_j_lt_i = trav_i.order(noarr::slice<'j'>(0, i_idx));

			trav_j_lt_i.template for_dims<'j'>([&](auto trav_ij) {
				auto state_ij = trav_ij.state();
				const std::size_t j_idx = get_index<'j'>(state_ij);

				// State for A[i][j]; we reuse this instead of re-creating
				// index states inside the inner k-loop.
				auto ij_state = state_ij;

				// A[i][j] -= sum_{k=0}^{j-1} A[i][k] * A[k][j]
				if (j_idx > 0) {
					k_trav_base
						.order(noarr::set_length<'k'>(j_idx))
						.for_each([&](auto k_state) {
							const std::size_t k_idx = get_index<'k'>(k_state);

							auto ik_state = noarr::idx<'i', 'j'>(i_idx, k_idx);
							auto kj_state = noarr::idx<'i', 'j'>(k_idx, j_idx);

							A[ij_state] -= A[ik_state] * A[kj_state];
						});
				}

				// A[i][j] /= A[j][j];
				auto jj_state = noarr::idx<'i', 'j'>(j_idx, j_idx);
				A[ij_state] /= A[jj_state];
			});
		}

		// -----------------------------------------------------------------
		// 2) Compute U-part for this row: columns i <= j < n
		//
		// Original order:
		//    for (j = i; j < n; ++j)
		//        for (k = 0; k < i; ++k)
